@exists_divFam_divFamDivisor_eq : ∀ {k : Type u_1} [inst : Field k] {C : Over (Spec (CommRingCat.of k))} {K : Type u_1}
  [inst_1 : Field K] [inst_2 : Algebra k K] {π : C.left ⟶ P1 k} [inst_3 : IsAffineHom π]
  [inst_4 : IsIntegral (relCurve C K)] [inst_5 : SmoothOfRelativeDimension 1 (relCurve C K ↘ Spec (CommRingCat.of K))]
  [inst_6 : QuasiCompact (relCurve C K ↘ Spec (CommRingCat.of K))] {n : ℕ} (D : (relCurve C K).CurveDivisor),
  0 ≤ D → Scheme.CurveDivisor.deg K D = ↑n → ∃ F, divFamDivisor F = D
